static int clr_trace_enabled(void) {
    static int enabled = -1;
    if (enabled < 0) {
        const char *value = getenv("VXRT_TRACE");
        enabled = value && *value == '1';
    }
    return enabled;
}

// VXRT_TRACE_CLR=1: the managed methods entered, one line each (without VXRT_TRACE's record of every Windows call).
static __thread uint32_t t_call_depth;   // managed calls on this host thread (each managed thread has its own)
static int clr_trace_methods_enabled(void) {
    static int enabled = -1;
    if (enabled < 0) {
        const char *value = getenv("VXRT_TRACE_CLR");
        enabled = clr_trace_enabled() || (value && *value == '1');
    }
    return enabled;
}

static void clr_trace(const char *format, ...) {
    va_list args;
    va_start(args, format);
    fputs("[vxrt] CLR ", stderr);
    vfprintf(stderr, format, args);
    fputc('\n', stderr);
    va_end(args);
}

#define CLR_MAX_ARGS 64u
#define CLR_MAX_LOCALS 256u
#define CLR_MAX_CALL_DEPTH 64u
#define CLR_MAX_STEPS 4000000000u          // a runaway guard only: a launcher parsing a 100k-entry manifest runs tens of millions
#define CLR_MAX_ASSEMBLIES 32u
#define CLR_MAX_ASSEMBLY_PATH 4096u
#define CLR_MAX_COLLECTION_ITEMS 4194304u   // a list or dictionary's elements (a game manifest lists ~100k files)
#define CLR_MAX_ARRAY_LENGTH 67108864u      // elements; a downloaded manifest is read into a byte[] of its size (~6 MB)
#define CLR_MAX_FORMAT_UNITS (1024u * 1024u)
#define CLR_MAX_PATH_UNITS 32768u

typedef enum { V_I4, V_I8, V_R4, V_R8, V_REF, V_MANAGED_PTR, V_FIELD_PTR } value_kind;
typedef struct { uint64_t bits; value_kind kind; } clr_value;
typedef struct { uint32_t token; clr_value value; } clr_static_field;
typedef struct { uint32_t token; uint8_t state; } clr_type_init;
typedef struct { struct clr_object *object; struct clr_module *module; uint32_t token; } clr_field_address;
typedef struct { char *name; clr_value value; } clr_setting;
typedef struct { char *name; struct clr_object *handler; } clr_event_binding;
typedef struct { struct clr_object *property; clr_value value; } clr_dependency_value;
typedef struct { int32_t left, top, right, bottom; } clr_wpf_rect;
typedef struct { int32_t x, y; } clr_wpf_point;
typedef struct {
    struct clr_object *object;
    clr_wpf_rect bounds;
    uint8_t input;
    uint8_t button;
    uint8_t hyperlink;
} clr_wpf_hit;
typedef struct {
    char family[96];
    char name[96];
    struct clr_object *object;
} clr_wpf_command;

typedef struct clr_module {
    const vx_dotnet_metadata *metadata;
    vx_dotnet_metadata owned_metadata;
    uint8_t *owned_image;
    size_t image_size;
    char name[256];
    clr_static_field *static_fields;
    uint32_t static_field_count;
    uint32_t static_field_capacity;
    clr_type_init *initialized_types;
    uint32_t initialized_type_count;
    uint32_t initialized_type_capacity;
    struct clr_method_cache_entry *method_cache;   // resolved methods by token (resolve_method is pure per module)
    uint32_t method_cache_capacity;
} clr_module;

typedef struct {
    clr_module *module;
    uint32_t token;
    clr_value value;
} clr_field;

typedef struct clr_object {
    clr_module *module;
    uint32_t type_token;
    const char *type_namespace;
    const char *type_name;
    char *owned_type_namespace;
    char *owned_type_name;
    const uint8_t *string_data;
    uint32_t string_units;
    uint8_t *owned_string_data;
    clr_value boxed_value;
    uint8_t is_boxed_value;
    struct clr_object **array_items;
    clr_value *array_values;
    uint32_t array_length;
    value_kind array_element_kind;
    uint8_t is_array;
    void *mutex_handle;
    HANDLE process_handle;
    DWORD process_id;
    uint8_t process_started;
    struct clr_object *process_start_info;
    FILE *io_stream;
    struct clr_object *referenced_object;
    struct clr_object *web_owner;
    struct clr_object *web_headers;
    uint8_t *web_upload;
    size_t web_upload_size;
    size_t web_upload_capacity;
    uint8_t *web_body;
    size_t web_body_size;
    size_t web_body_capacity;
    size_t web_body_position;
    uint32_t web_status;
    uint8_t web_stream_kind; // 1: request body, 2: response body
    uint8_t web_stream_closed;
    struct clr_object *startup_uri;
    struct clr_object *startup_handler;
    struct clr_object *exit_handler;
    struct clr_object *unhandled_handler;
    uint8_t wpf_loaded;                 // Loaded has been raised for this element
    struct clr_object **connected;      // a component root: the elements its Connect() wired (for Initialized / Loaded)
    uint32_t connected_count, connected_capacity;
    struct clr_object *delegate_target;
    struct clr_object *delegate_next;    // a multicast delegate: the next entry of its invocation list (Delegate.Combine)
    clr_module *delegate_module;
    uint32_t delegate_method;
    clr_module *reflection_module;
    uint32_t reflection_token;
    pthread_mutex_t monitor;
    uint8_t monitor_initialized;
    uint8_t task_completed;
    uint8_t task_succeeded;
    struct clr_object *task_exception;
    struct clr_object *wpf_parent;
    struct clr_object *wpf_content;
    uint32_t wpf_visibility;
    struct clr_object *wpf_input_gestures;
    char wpf_command_name[192];
    uint32_t wpf_key;
    uint32_t wpf_modifiers;
    struct clr_object **wpf_items;
    uint32_t wpf_item_count;
    uint32_t wpf_item_capacity;
    struct clr_object **dictionary_keys;
    clr_value *map_keys;
    clr_value *map_values;
    uint32_t *map_index;             // a hash index over map_keys (dictionaries) or wpf_items (sets): entry + 1 per slot
    uint32_t map_index_capacity, map_index_count;
    clr_value pair_key;
    clr_value pair_value;
    struct clr_object *collection_owner;
    int32_t enumerator_index;
    uint8_t is_sorted_dictionary;
    uint8_t is_dictionary;
    uint8_t is_key_value_pair;
    uint8_t collection_view;       // 1: SortedDictionary.Keys, 2: SortedDictionary.Values
    uint8_t enumerator_kind;       // 1: List/HashSet, 2: dictionary keys, 3: dictionary values
    clr_event_binding *wpf_events;
    uint32_t wpf_event_count;
    uint32_t wpf_event_capacity;
    clr_module *wpf_dp_owner_module;
    uint32_t wpf_dp_owner_token;
    clr_module *wpf_dp_value_module;
    uint32_t wpf_dp_value_token;
    char wpf_dp_name[192];
    clr_dependency_value *wpf_dp_values;
    uint32_t wpf_dp_value_count;
    uint32_t wpf_dp_value_capacity;
    uint64_t wpf_timer_interval;
    uint8_t wpf_timer_running;
    uint32_t component_record_count;
    char component_key[512];
    clr_field *fields;
    uint32_t field_count;
    uint32_t field_capacity;
    clr_setting *settings;
    uint32_t setting_count;
    uint32_t setting_capacity;
    uint8_t is_query_collection;
    uint8_t is_nullable;           // a System.Nullable<T> value: boxed_value when nullable_has_value
    uint8_t nullable_has_value;
    clr_value task_result;         // a Task<T>'s result (and its builder's), once set
    uint32_t builder_capacity;     // a StringBuilder's room, in UTF-16 units (its text is owned_string_data, string_units long)
    void *redirect_read;           // a Process's redirected standard output: the pipe's read handle, until it is read
} clr_object;

